package com.aratech.moveis.embalagem.repository;

import com.aratech.moveis.embalagem.dto.*;
import com.aratech.moveis.fabricacao.dto.*;
import com.aratech.moveis.security.exception.AuthException;
import com.aratech.moveis.shared.dto.Pagina;
import lombok.RequiredArgsConstructor;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import tools.jackson.databind.json.JsonMapper;
import java.sql.*;
import java.time.*;
import java.util.*;

@Repository
@RequiredArgsConstructor
public class EmbalagemRepository {
    private final JdbcTemplate jdbc;private final JsonMapper json;
    private static final String TEMPO="e.segundos_ativos+CASE WHEN e.status='EM_EXECUCAO' THEN GREATEST(0,EXTRACT(EPOCH FROM (CURRENT_TIMESTAMP-e.inicio_atual))::bigint) ELSE 0 END";
    private static final String LIBERADA="NOT EXISTS(SELECT 1 FROM embalagem_etapa anterior WHERE anterior.lote_id=e.lote_id AND anterior.sequencia<e.sequencia AND anterior.status<>'CONCLUIDA')";
    public List<Esteira> esteiras(String busca,boolean ativas) {
        return jdbc.query("SELECT * FROM embalagem_esteira WHERE (?=FALSE OR ativo) AND (strpos(lower(codigo||' '||nome||' '||atividade||' '||responsavel),lower(?))>0) ORDER BY ativo DESC,lower(nome),id LIMIT 100",(r,n)->lerEsteira(r),ativas,busca);
    }
    private Esteira lerEsteira(ResultSet r)throws SQLException{return new Esteira(r.getLong("id"),r.getString("codigo"),r.getString("nome"),r.getString("atividade"),r.getString("responsavel"),r.getInt("capacidade"),r.getBoolean("ativo"),r.getString("observacoes"),r.getLong("versao"));}
    public Esteira esteira(long id,boolean bloquear){var v=jdbc.query("SELECT * FROM embalagem_esteira WHERE id=?"+(bloquear?" FOR UPDATE":""),(r,n)->lerEsteira(r),id);if(v.isEmpty())throw new AuthException(404,"Esteira não encontrada.");return v.getFirst();}
    public long criarEsteira(EsteiraEntrada d){return jdbc.queryForObject("INSERT INTO embalagem_esteira(codigo,nome,atividade,responsavel,capacidade,ativo,observacoes) VALUES (?,?,?,?,?,?,?) RETURNING id",Long.class,d.codigo().strip(),d.nome().strip(),d.atividade().strip(),Objects.toString(d.responsavel(),""),d.capacidade(),d.ativo(),Objects.toString(d.observacoes(),""));}
    public void editarEsteira(long id,EsteiraEntrada d){jdbc.update("UPDATE embalagem_esteira SET codigo=?,nome=?,atividade=?,responsavel=?,capacidade=?,ativo=?,observacoes=?,versao=versao+1 WHERE id=?",d.codigo().strip(),d.nome().strip(),d.atividade().strip(),Objects.toString(d.responsavel(),""),d.capacidade(),d.ativo(),Objects.toString(d.observacoes(),""),id);}
    public int ocupadas(long id){return jdbc.queryForObject("SELECT count(*) FROM embalagem_etapa WHERE esteira_id=? AND status IN ('EM_EXECUCAO','PAUSADA')",Integer.class,id);}
    public int pendentes(long id){return jdbc.queryForObject("SELECT count(*) FROM embalagem_etapa WHERE esteira_id=? AND status IN ('AGUARDANDO','EM_EXECUCAO','PAUSADA')",Integer.class,id);}
    public List<TarefaEsteira> tarefas(long esteira,boolean trabalhando){String filtro=trabalhando?"e.status IN ('EM_EXECUCAO','PAUSADA')":"e.status='AGUARDANDO' AND "+LIBERADA;return jdbc.query("SELECT e.*,l.versao,l.quantidade,l.previsao,l.prioridade,l.ficha->'ficha'->>'nome' modelo,"+TEMPO+" tempo,NOT EXISTS(SELECT 1 FROM embalagem_etapa p WHERE p.lote_id=e.lote_id AND p.sequencia>e.sequencia) ultima FROM embalagem_etapa e JOIN embalagem_lote l ON l.id=e.lote_id WHERE e.esteira_id=? AND l.status NOT IN ('CANCELADO','EMBALADO') AND "+filtro+" ORDER BY CASE l.prioridade WHEN 'URGENTE' THEN 0 WHEN 'ALTA' THEN 1 ELSE 2 END,l.previsao,l.id LIMIT 100",(r,n)->new TarefaEsteira(r.getLong("id"),r.getLong("lote_id"),r.getLong("versao"),r.getInt("sequencia"),r.getString("modelo"),r.getInt("quantidade"),r.getDate("previsao").toLocalDate(),r.getString("prioridade"),r.getString("nome"),r.getString("instrucoes"),r.getString("status"),r.getString("operador"),r.getString("motivo_pausa"),r.getLong("tempo"),r.getBoolean("ultima")),esteira);}
    public int futuras(long esteira){return jdbc.queryForObject("SELECT count(*) FROM embalagem_etapa e WHERE e.esteira_id=? AND e.status='AGUARDANDO' AND NOT ("+LIBERADA+")",Integer.class,esteira);}
    public List<EtapaEmbalagem> etapas(long lote){return jdbc.query("SELECT e.*,s.nome esteira,"+TEMPO+" tempo,"+LIBERADA+" liberada FROM embalagem_etapa e JOIN embalagem_esteira s ON s.id=e.esteira_id WHERE e.lote_id=? ORDER BY e.sequencia",(r,n)->new EtapaEmbalagem(r.getLong("id"),r.getLong("lote_id"),r.getInt("sequencia"),r.getLong("esteira_id"),r.getString("esteira"),r.getString("nome"),r.getString("instrucoes"),r.getString("status"),r.getString("operador"),r.getLong("tempo"),instante(r,"iniciado_em"),instante(r,"concluido_em"),r.getString("motivo_pausa"),r.getBoolean("liberada")),lote);}
    public long loteDaEtapa(long id){var ids=jdbc.queryForList("SELECT lote_id FROM embalagem_etapa WHERE id=?",Long.class,id);if(ids.isEmpty())throw new AuthException(404,"Etapa não encontrada.");return ids.getFirst();}
    public LoteEmbalagem lote(long id,boolean bloquear){var lotes=jdbc.query("SELECT * FROM embalagem_lote WHERE id=?"+(bloquear?" FOR UPDATE":""),(r,n)->new LoteEmbalagem(r.getLong("id"),r.getLong("origem_id"),r.getString("status"),r.getLong("versao"),r.getInt("quantidade"),r.getDate("previsao").toLocalDate(),r.getString("prioridade"),r.getString("observacoes"),(Integer)r.getObject("volumes"),instante(r,"criado_em"),instante(r,"concluido_em"),json.readValue(r.getString("ficha"),ModeloGuardaRoupa.class),List.of(),List.of()),id);if(lotes.isEmpty())throw new AuthException(404,"Lote de embalagem não encontrado.");var l=lotes.getFirst();return new LoteEmbalagem(l.id(),l.origemId(),l.status(),l.versao(),l.quantidade(),l.previsao(),l.prioridade(),l.observacoes(),l.volumes(),l.criadoEm(),l.concluidoEm(),l.modelo(),etapas(id),historico(id));}
    private Instant instante(ResultSet r,String coluna)throws SQLException{var t=r.getTimestamp(coluna);return t==null?null:t.toInstant();}
    public List<EventoEmbalagem> historico(long lote){return jdbc.query("SELECT * FROM embalagem_evento WHERE lote_id=? ORDER BY id DESC",(r,n)->new EventoEmbalagem(r.getLong("id"),(Long)r.getObject("etapa_id"),r.getString("acao"),r.getString("detalhe"),r.getString("autor"),r.getTimestamp("criado_em").toInstant()),lote);}
    public long criarLote(NovoLoteEmbalagem d,LoteCorte origem){long id=jdbc.queryForObject("INSERT INTO embalagem_lote(origem_id,ficha,quantidade,previsao,prioridade,observacoes,chave_operacao) VALUES (?,?::jsonb,?,?,?,?,?) RETURNING id",Long.class,d.origemId(),json.writeValueAsString(origem.modelo()),origem.quantidade(),d.previsao(),d.prioridade().name(),Objects.toString(d.observacoes(),""),d.chaveOperacao());int n=0;for(var e:d.etapas())jdbc.update("INSERT INTO embalagem_etapa(lote_id,sequencia,esteira_id,nome,instrucoes) VALUES (?,?,?,?,?)",id,++n,e.esteiraId(),e.nome().strip(),Objects.toString(e.instrucoes(),""));return id;}
    public boolean recebido(long origem){return jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM embalagem_lote WHERE origem_id=? AND status<>'CANCELADO')",Boolean.class,origem);}
    public Pagina<LoteResumo> origens(int pagina,int tamanho,String busca){String f=" WHERE f.status='CORTADO' AND NOT EXISTS(SELECT 1 FROM embalagem_lote l WHERE l.origem_id=f.id AND l.status<>'CANCELADO') AND (strpos(lower(f.ficha->'ficha'->>'nome'),lower(?))>0 OR CAST(f.id AS TEXT)=?)";Long total=jdbc.queryForObject("SELECT count(*) FROM fabricacao_lote f"+f,Long.class,busca,busca);var itens=jdbc.query("SELECT f.id,f.ficha->'ficha'->>'codigo' codigo,f.ficha->'ficha'->>'nome' nome,f.quantidade,f.previsao,f.status,f.versao FROM fabricacao_lote f"+f+" ORDER BY f.concluido_em,f.id LIMIT ? OFFSET ?",(r,n)->new LoteResumo(r.getLong("id"),r.getString("codigo"),r.getString("nome"),r.getInt("quantidade"),r.getDate("previsao").toLocalDate(),r.getString("status"),r.getLong("versao")),busca,busca,tamanho,(long)pagina*tamanho);return new Pagina<>(itens,total,pagina,tamanho);}
    public Pagina<ResumoEmbalagem> lotes(int pagina,int tamanho,String busca,String status){String f=" WHERE (?='' OR l.status=?) AND (strpos(lower(l.ficha->'ficha'->>'nome'),lower(?))>0 OR CAST(l.id AS TEXT)=? OR CAST(l.origem_id AS TEXT)=?)";Long total=jdbc.queryForObject("SELECT count(*) FROM embalagem_lote l"+f,Long.class,status,status,busca,busca,busca);var itens=jdbc.query("SELECT l.*,(SELECT count(*) FROM embalagem_etapa e WHERE e.lote_id=l.id AND e.status='CONCLUIDA') concluidas,(SELECT count(*) FROM embalagem_etapa e WHERE e.lote_id=l.id) total,(SELECT e.nome FROM embalagem_etapa e WHERE e.lote_id=l.id AND e.status NOT IN ('CONCLUIDA','CANCELADA') ORDER BY e.sequencia LIMIT 1) etapa,(SELECT s.nome FROM embalagem_etapa e JOIN embalagem_esteira s ON s.id=e.esteira_id WHERE e.lote_id=l.id AND e.status NOT IN ('CONCLUIDA','CANCELADA') ORDER BY e.sequencia LIMIT 1) esteira FROM embalagem_lote l"+f+" ORDER BY CASE WHEN l.status IN ('EMBALADO','CANCELADO') THEN 1 ELSE 0 END,CASE l.prioridade WHEN 'URGENTE' THEN 0 WHEN 'ALTA' THEN 1 ELSE 2 END,l.previsao,l.id LIMIT ? OFFSET ?",(r,n)->new ResumoEmbalagem(r.getLong("id"),r.getLong("origem_id"),json.readTree(r.getString("ficha")).path("ficha").path("nome").asText(),r.getInt("quantidade"),r.getDate("previsao").toLocalDate(),r.getString("prioridade"),r.getString("status"),r.getLong("versao"),r.getInt("concluidas"),r.getInt("total"),r.getString("etapa"),r.getString("esteira"),(Integer)r.getObject("volumes")),status,status,busca,busca,busca,tamanho,(long)pagina*tamanho);return new Pagina<>(itens,total,pagina,tamanho);}
    public void operar(long etapa,String acao,String operador,String motivo){String sql=switch(acao){case "iniciar","retomar"->"status='EM_EXECUCAO',operador=?,inicio_atual=CURRENT_TIMESTAMP,iniciado_em=COALESCE(iniciado_em,CURRENT_TIMESTAMP)";case "pausar"->"status='PAUSADA',motivo_pausa=?,segundos_ativos=segundos_ativos+GREATEST(0,EXTRACT(EPOCH FROM(CURRENT_TIMESTAMP-inicio_atual))::bigint),inicio_atual=NULL";case "concluir"->"status='CONCLUIDA',segundos_ativos=segundos_ativos+GREATEST(0,EXTRACT(EPOCH FROM(CURRENT_TIMESTAMP-inicio_atual))::bigint),inicio_atual=NULL,concluido_em=CURRENT_TIMESTAMP";default->throw new IllegalArgumentException("Ação inválida");};if(acao.equals("concluir"))jdbc.update("UPDATE embalagem_etapa SET "+sql+" WHERE id=?",etapa);else jdbc.update("UPDATE embalagem_etapa SET "+sql+" WHERE id=?",acao.equals("pausar")?motivo:operador,etapa);}
    public void statusLote(long lote,String status,Integer volumes){jdbc.update("UPDATE embalagem_lote SET status=?,versao=versao+1,volumes=COALESCE(?,volumes),concluido_em=CASE WHEN ?='EMBALADO' THEN CURRENT_TIMESTAMP ELSE concluido_em END WHERE id=?",status,volumes,status,lote);}
    public void cancelarEtapas(long lote){jdbc.update("UPDATE embalagem_etapa SET status='CANCELADA' WHERE lote_id=?",lote);}
    public void evento(long lote,Long etapa,String acao,String detalhe,String autor){jdbc.update("INSERT INTO embalagem_evento(lote_id,etapa_id,acao,detalhe,autor) VALUES (?,?,?,?,?)",lote,etapa,acao,detalhe,autor);}
}
